-- chair-step: canonicalization lane 4 sets organization_id NOT NULL on six rag tables (0 null rows after a named backfill; every writer already passes it) and retires rag.data_stores' bespoke set_updated_at trigger into the canonical _touch_row
-- lane: canonicalization lane 4 (schemas rag, files, docproc, pdf) — batch 1, the cheap certifications.
--
-- 1. files.analysis / analysis_result / pages / page_annotations (components of file): rules
--    regenerated by iam.apply_rls so each carries the generator's org_open_gate. Proven in a
--    rolled-back transaction: only legacy_owner_col remains on analysis/pages/page_annotations.
-- 2. rag.kg_sweep_state: base visibility column (platform.visibility, default 'internal' —
--    Organization, the doctrine default). Constant default: catalogue-only, no rewrite.
-- 3. rag.data_stores: two rows carried no organization (created 2026-08-09/10, before the
--    no-org law). NAMED rule: the owner's signup organization = the earliest iam.organizations row
--    the owner (created_by) created. Then NOT NULL, base version column, _touch_row replaces
--    trg_data_stores_updated_at (set_updated_at). Writers: matrx_rag.data_stores.create_data_store
--    refuses a blank organization_id; features/rag/hooks/useDataStores.ts inserts organization_id.
-- 4. organization_id NOT NULL on rag.context_item_suggestions, kg_alerts, kg_value_matches,
--    ner_canonicalizer_shadow, scope_suggestions — 0 null rows today (measured 2026-10-22).
set lock_timeout = '2s';

-- 1
select iam.apply_rls('files', 'analysis', 'file_analysis', 'component');
select iam.apply_rls('files', 'analysis_result', 'analysis_result', 'component');
select iam.apply_rls('files', 'pages', 'file_pages', 'component');
select iam.apply_rls('files', 'page_annotations', 'file_page_annotations', 'component');

-- 2
alter table rag.kg_sweep_state add column if not exists visibility platform.visibility not null default 'internal';

-- 3
update rag.data_stores d
   set organization_id = (select o.id from iam.organizations o
                           where o.created_by = d.created_by
                           order by o.created_at limit 1)
 where d.organization_id is null;
alter table rag.data_stores alter column organization_id set not null;
alter table rag.data_stores add column if not exists version int not null default 1;
drop trigger if exists trg_data_stores_updated_at on rag.data_stores;
drop trigger if exists _touch_row on rag.data_stores;
create trigger _touch_row before insert or update on rag.data_stores
  for each row execute function platform._touch_row();

-- 4
alter table rag.context_item_suggestions alter column organization_id set not null;
alter table rag.kg_alerts                alter column organization_id set not null;
alter table rag.kg_value_matches         alter column organization_id set not null;
alter table rag.ner_canonicalizer_shadow alter column organization_id set not null;
alter table rag.scope_suggestions        alter column organization_id set not null;

do $$ begin
  if exists (select 1 from iam.verify_canonical('rag', 'data_stores', 'data_store', 'entity') where status in ('FAIL','WARN')) then raise exception 'rag.data_stores still has findings'; end if;
  if exists (select 1 from iam.verify_canonical('rag', 'kg_sweep_state', 'kg_sweep_state', 'entity') where status in ('FAIL','WARN')) then raise exception 'rag.kg_sweep_state still has findings'; end if;
  if exists (select 1 from iam.verify_canonical('files', 'analysis_result', 'analysis_result', 'component') where status in ('FAIL','WARN')) then raise exception 'files.analysis_result still has findings'; end if;
end $$;
